insert into product_images (product_id, storage_bucket, storage_path, file_name, sort_order, is_primary, metadata)
select p.id, 'external', v.url, v.name, v.sort_order, v.is_primary, v.meta || '{"seeded_by":"library-pictures-2026-10-17"}'::jsonb
from v
join products p on p.metadata->'library'->>'drive_folder_id' = v.folder
               and p.metadata->'library'->>'imported_by' = 'library-connect-2026-10-17'
where not exists (select 1 from product_images i
                  where i.product_id = p.id and i.metadata->>'drive_file_id' = v.meta->>'drive_file_id');
commit;

-- Check: expect 33 products, each with 3–6 pictures
select p.title, count(i.id) as pictures
from products p left join product_images i on i.product_id = p.id and i.metadata->>'source' = 'drive'
where p.metadata->'library'->>'imported_by' = 'library-connect-2026-10-17'
group by p.title order by p.title;
